  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Approves the application if and only if it is currently pending and the related customer is still eligible for IPO.
   * When approved, the application status becomes APPROVAL and two information emails are created: one for the customer and one for the company.
   * Algorithm:
   * 1. Check whether status == PENDING.
   * 2. Check whether customer.isEligibleForIPO() == true.
   * 3. If either check fails, return false.
   * 4. Set status to APPROVAL.
   * 5. Create one Email for the customer and one Email for the company.
   * 6. Store both emails in emails.
   * 7. Return true.
   * Related Features:
   * - status
   * - customer
   * - company
   * - share
   * - amountOfMoney
   * - emails
   * Related Classes: Customer, Company, Email, ApplicationStatus
   * Input:
   * - No explicit parameters.
   * - Uses the current Application instance state.
   * Output:
   * - boolean:
   *   - true if the application is approved successfully.
   *   - false otherwise.
   * Pre-condition:
   * - The application instance must be initialized.
   * - The application must have a linked customer and company.
   * - The application status must be PENDING.
   * - The customer must be eligible for IPO.
   * Post-condition:
   * - If the operation returns true, status is set to APPROVAL.
   * - Two information emails are created and stored in emails, one for the customer and one for the company.
   * - The application remains unchanged if the operation returns false.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean approve()
  {
    if (getStatus() != ApplicationStatus.PENDING)
    {
      return false;
    }
    Customer customer = getCustomer();
    Company company = getCompany();
    if (customer == null || company == null || !customer.isEligibleForIPO())
    {
      return false;
    }

    setStatus(ApplicationStatus.APPROVAL);

    Email customerEmail = IpoFactory.eINSTANCE.createEmail();
    customerEmail.setReceiver(customer.getEmail());
    customerEmail.setContent(customerEmail.createEmailContent(company, getShare(), customer, getAmountOfMoney()));

    Email companyEmail = IpoFactory.eINSTANCE.createEmail();
    companyEmail.setReceiver(company.getEmail());
    companyEmail.setContent(companyEmail.createEmailContent(company, getShare(), customer, getAmountOfMoney()));

    getEmails().add(customerEmail);
    getEmails().add(companyEmail);

    return true;
  }

